mapper.select:
select p.name_th as 'productNameTh', p.name_en as 'productNameEn' , p.bar_code as 'barCode', ped.cost_price as 'costPrice', ped.sell_price as 'sellPrice', ped.expire_date as 'expireDate', ps.code as 'statusCode', ps.name_th as 'statusNameTh', ps.name_en as 'statusNameEn' from MS_PRODUCTS p left join MS_PRODUCT_GROUPS pg on p.product_group_code = pg.code left join TR_PRODUCT_EXPIRE_DATE ped on p.code = ped.product_code left join MS_PRODUCT_STATUS ps on ped.product_status_code = ps.code
AND p.name_th like concat('%', #{searchNameTh} ,'%')
AND p.name_en like concat('%', #{searchNameEn} ,'%')
AND p.bar_code like concat('%', #{searchBarCode} ,'%')
AND ped.cost_price >= #{searchMinCostPrice}
AND ped.cost_price <= #{searchMaxCostPrice}
AND ped.sell_price >= #{searchMinSellPrice}
AND ped.sell_price <= #{searchMaxSellPrice}
AND DATE(ped.expire_date) >= DATE(#{searchStartDate})
AND DATE(ped.expire_date) <= DATE(#{searchEndDate})
AND ps.code = #{searchStatusCode}
